function s(){const o=document.querySelectorAll("[data-reveal]");if(!("IntersectionObserver"in window)||o.length===0){o.forEach(e=>e.classList.add("is-visible"));return}const t=new IntersectionObserver(e=>{for(const n of e)n.isIntersecting&&(n.target.classList.add("is-visible"),t.unobserve(n.target))},{threshold:.15,rootMargin:"0px 0px -8% 0px"});o.forEach(e=>t.observe(e))}function c(){document.querySelectorAll(".prose pre:not([data-copy-ready])").forEach(t=>{t.setAttribute("data-copy-ready","true");const e=document.createElement("button");e.type="button",e.className="code-copy-btn",e.textContent="Copy",e.setAttribute("aria-label","Copy code to clipboard"),e.addEventListener("click",async()=>{const n=t.querySelector("code")?.innerText??t.innerText;try{await navigator.clipboard.writeText(n),e.textContent="Copied!",e.classList.add("is-copied")}catch{e.textContent="Failed"}setTimeout(()=>{e.textContent="Copy",e.classList.remove("is-copied")},1800)}),t.appendChild(e)})}s();c();document.addEventListener("astro:page-load",()=>{s(),c()});const i=document.getElementById("mobile-menu-toggle"),r=document.getElementById("mobile-menu");i?.addEventListener("click",()=>{const o=r?.classList.toggle("hidden")===!1;i.setAttribute("aria-expanded",String(o))});
